#!/usr/bin/env bash
# Fails when the committed MSW worker (web/mocks/mockServiceWorker.js) was generated by a different msw than the one installed, so an msw upgrade can't land without refreshing it. [web] is the web directory, web by default; run it after installing its dependencies.
#
# msw 3 has no postinstall to refresh the worker, and Renovate doesn't run install scripts anyway, so an upgrade PR changes only package.json and the lockfile. Fix a failure with pnpm -C web exec msw init mocks --no-save.
set -euo pipefail

if [[ $# -gt 1 ]]; then
  echo "usage: $0 [web]" >&2
  exit 2
fi

web="${1:-web}"
worker="${web}/mocks/mockServiceWorker.js"
manifest="${web}/node_modules/msw/package.json"

if [[ ! -f "${worker}" ]]; then
  echo "${worker} doesn't exist" >&2
  exit 1
fi

if [[ ! -f "${manifest}" ]]; then
  echo "msw isn't installed in ${web}; run pnpm -C ${web} install first" >&2
  exit 1
fi

worker_version="$(sed -n "s/^const PACKAGE_VERSION = '\([^']*\)'$/\1/p" "${worker}")"
installed_version="$(node -p 'require(process.argv[1]).version' "$(realpath "${manifest}")")"

if [[ -z "${worker_version}" ]]; then
  echo "${worker} has no PACKAGE_VERSION" >&2
  exit 1
fi

if [[ "${worker_version}" != "${installed_version}" ]]; then
  echo "${worker} is from msw ${worker_version} but msw ${installed_version} is installed; refresh it with pnpm -C ${web} exec msw init mocks --no-save" >&2
  exit 1
fi

echo "${worker} matches msw ${installed_version}"
